import shutil, os, glob

# Remove common build/output directories
for p in ['build', 'dist', '.cache', '.mypy_cache', '.pytest_cache', 'node_modules', 'target', '.tox', '.venv']:
    if os.path.isdir(p):
        shutil.rmtree(p)

# Remove all __pycache__ directories
for p in glob.glob('**/__pycache__', recursive=True):
    if os.path.isdir(p):
        shutil.rmtree(p)

# Remove compiled Python files
for p in glob.glob('**/*.pyc', recursive=True):
    os.remove(p)

# Remove egg-info directories
for p in glob.glob('*.egg-info'):
    if os.path.isdir(p):
        shutil.rmtree(p)

print('Clean complete.')
